import{_ as l,C as t,o,c as d,E as a,a2 as n}from"./chunks/framework.VWKgVqrc.js";const m=JSON.parse('{"title":"解读串谋分数之前，先看标签留下了谁","description":"","frontmatter":{"title":"解读串谋分数之前，先看标签留下了谁","article_type":"technical-analysis","edition":"research-center","research_question":"严格选择标签依据哪些证据保留或排除样本，这会怎样限制监测分数的解读？","summary":"严格标签同时读取目标投票与私有立场。混合信号被排除，缺失立场按非阳性处理；理解分数需要同时披露证据完整性与保留人群。","sources":"arXiv:2611.10620v1; pinned collusion-probe-pitfalls source and stored author results; corrected archive metadata","date":"2026-11-12","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261112-006","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-12-sig-20261112-006-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-12-sig-20261112-006.md","filePath":"zh/engineering/2026-11-12-sig-20261112-006.md","lastUpdated":null}'),s={name:"zh/engineering/2026-11-12-sig-20261112-006.md"};function p(c,e,h,b,u,g){const r=t("ArticleCover"),i=t("ArticleTableScroll");return o(),d("div",null,[a(r,{image:"/assets/covers/daily-2026-11-12-sig-20261112-006-cover.png",kicker:"研究成果",title:"解读串谋分数之前，先看标签留下了谁",summary:"严格标签同时读取目标投票与私有立场。混合信号被排除，缺失立场按非阳性处理；理解分数需要同时披露证据完整性与保留人群。",version:"2026-11-12",languageHref:"/en/engineering/2026-11-12-sig-20261112-006",languageLabel:"English"}),a(i,{language:"zh"}),e[0]||(e[0]=n('<h1 id="解读串谋分数之前-先看标签留下了谁" tabindex="-1">解读串谋分数之前，先看标签留下了谁 <a class="header-anchor" href="#解读串谋分数之前-先看标签留下了谁" aria-label="Permalink to &quot;解读串谋分数之前，先看标签留下了谁&quot;">​</a></h1><p>一个样本投了目标票，却没有可读的私有立场记录。在我们对固定源码的合成输入检查中，它没有得到“参与”的严格标签，而是被排除。若同样缺少立场记录、也没有投目标票，函数则会给出否定标签。分数之前，证据的可得性和组合规则已经在选择谁进入比较。</p><p>这不是监测器失效的证据。本文的判断更具体：解读多智能体串谋监测结果时，应同时知道标签需要什么证据、哪些样本被排除，以及缺失证据如何处理。否则，一个有效的排序分数也可能回答了比读者以为更窄的问题。</p><h2 id="严格标签先定义比较人群" tabindex="-1">严格标签先定义比较人群 <a class="header-anchor" href="#严格标签先定义比较人群" aria-label="Permalink to &quot;严格标签先定义比较人群&quot;">​</a></h2><p>已读研究同时讨论指令线索、决策线索与监测分数。我们检查的严格选择标签函数，并非只问“有没有投目标票”：它还读取私有消息中的立场信号，把两种判断组合起来。固定源码的严格模式保留两者都为阳性的样本为真，两者都非阳性的样本为假；两者不一致时返回空值，排除出该严格比较。[1][2]</p><p>这里有一项重要区别：空值不是另一个否定标签，而是不纳入该比较。把“投票或私有同意任一为真”换成“二者都为真”，不仅改变正类定义，还改变被保留的样本集合。严格模式可提高标签一致性，但由它得到的分数针对的是这个经过筛选的人群。这是对测量机制的解释，不是重新计算作者数据后的统计发现。</p><p>所读实现按场景组交叉拟合，并使用第 1–4 轮。代码能表明这些预定处理方式，却不能单独证明每份真实片段的标注正确，也不能代替对片段内容与计算输出的重算。[2]</p><h2 id="六个合成用例揭示了什么" tabindex="-1">六个合成用例揭示了什么 <a class="header-anchor" href="#六个合成用例揭示了什么" aria-label="Permalink to &quot;六个合成用例揭示了什么&quot;">​</a></h2><p>本次研究分析在固定提交上，抽取并执行严格选择标签与选项重标记函数。使用的是合成配置文件和立场文件，不是论文数据集。环境缺少 NumPy（数值计算库），因此仅对用例中的简单标量列表，以 Python（编程语言）标准库的均值函数代替其均值调用；没有模拟数组运算、训练或模型推理。[3]</p><table tabindex="0"><thead><tr><th>合成条件</th><th>宽松标签：任一阳性</th><th>严格标签：要求一致</th></tr></thead><tbody><tr><td>目标投票阳性，私有立场阳性</td><td>真</td><td>真</td></tr><tr><td>仅目标投票阳性</td><td>真</td><td>空值，排除</td></tr><tr><td>仅私有立场阳性</td><td>真</td><td>空值，排除</td></tr><tr><td>二者均非阳性</td><td>假</td><td>假</td></tr><tr><td>私有立场缺失，但目标投票阳性</td><td>真</td><td>空值，排除</td></tr><tr><td>私有立场缺失，且目标投票非阳性</td><td>假</td><td>假</td></tr></tbody></table><p>表格来源是本研究的内部隔离函数实验，不是独立第三方复现。六个用例中的严格标签保留一个真、两个假，并排除三个。这个计数仅描述人为构造的六个用例，不能用作真实数据的覆盖率或缺失比例。[3]</p><p>缺失私有立场时，所测函数把相应判断按非阳性处理。这使最后一个用例与“实际测得两种证据都非阳性”得到相同标签，但两者的证据状态不同。前者不能被不加说明地描述为“观察到拒绝”。如果拿掉整个立场文件，原先双阳性的用例也会因仅剩目标投票而被排除；原先仅私有立场阳性的用例则变为假。这说明标签依赖的证据面，而不是证明公开数据真的发生了缺失。[3]</p><p>同一次隔离实验还检查了四种选项标签组合及不应匹配的文本。固定生成器按当前公平选项与目标选项重写规范形式的选项引用，观察结果符合这四组用例的预期。它说明所测文本替换行为，不能保证所有真实片段的选项语义和立场标签都正确。[3][4]</p><h2 id="排序、误报与读取时点不能互换" tabindex="-1">排序、误报与读取时点不能互换 <a class="header-anchor" href="#排序、误报与读取时点不能互换" aria-label="Permalink to &quot;排序、误报与读取时点不能互换&quot;">​</a></h2><p>作者报告，在委员会数据的困难负例比较中，移除简报与私有上下文后，智能体级 AUROC（受试者工作特征曲线下面积，用于衡量排序区分能力）从 1.00 降到 0.61；同提示的决策探针保留 0.73。这项干预同时改变输入分布，因此不能单独识别分数究竟来自目标还是上下文线索。[1]</p><p>较高的排序能力也不保证某个运行阈值的误报率。作者报告，委员会与代码评审之间迁移的排序分数为 0.994 与 0.966，但按源域 1% 误报设置的阈值在目标域产生 2.5% 与 4.0% 误报；未经重训的探针在所用涌现串谋片段上为 0.50。这些数值仍是作者的实验结果，不是本次函数检查的测量。[1]</p><p>已读取的作者结果文件还给出一个更直接的例子：无简报实验中的指令探针对诚实适配器的排序分数为 0.99468，同时对照组运行级误报为 0.21212 与 0.28283；决策探针标记了 14% 的植入运行，对照组没有观察到误报。这里的观测单位不同，不能把智能体级排序指标与运行级告警表现互相替代。“零观察误报”也不能扩写成没有误报风险。[5]</p><p>读取时间同样决定问题。作者的事后投票规则在成功尝试上的排序分数达到 0.990，但投票之前没有结果可读；主评估则在投票前对所有尝试评分。事后筛查与事前识别有不同信息条件和样本条件。严格标签的机制探针既没有重算这些数字，也不能据此修正或否定它们。[1]</p><p>我们据此提出的工程解释是：一份监测评估应把目标行为定义、标签所需证据、保留与排除数量、评分时点、观测单位，以及实际阈值的误报一并交代。它们决定读者能把分数用于什么判断。</p><h2 id="追求标签纯度-有合理的使用边界" tabindex="-1">追求标签纯度，有合理的使用边界 <a class="header-anchor" href="#追求标签纯度-有合理的使用边界" aria-label="Permalink to &quot;追求标签纯度，有合理的使用边界&quot;">​</a></h2><p>严格标签并非天然错误。研究者可以有意排除混合信号，以便比较证据一致的参与者与非参与者。若真实片段的私有立场文件完整，缺失分支可能根本不影响原研究的结果。本次合成实验没有证据认定完整数据的预期用法存在缺陷。</p><p>相应代价是覆盖范围需要可见：排除的混合行为可能正是部署时仍会遇到的对象。本文没有测量它们在实际系统中多常见，也没有研究对抗规避或自发秘密串谋。标签依赖生成器与立场模型，并非所有审计标记的运行都由人类复核；这些限制继续约束解释。[1][2]</p><p>归档元数据把 1.2 标为修正版，并说明补跑了 1.1 中遗漏的隐蔽消息分析；预注册修订还记录了选项标签问题影响主要尝试中的 572/1000，适配器未重训。这些是版本及作者修订记录。我们没有取得修正后的原始片段与激活值，没有重算自举或验证其完整输出，植入适配器权重也未公开。归档身份和 DOI（数字对象标识符）不能替代这些实证缺口。[1][4][6]</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文的公开一手事实是固定源码及版本记录可直接显示的处理方式。本次观察说明读过哪些代码路径；内部实验依据只说明合成输入下所选函数的输出。模型效果和统计指标全部是来源陈述，没有冒充独立证据。本研究没有训练适配器、运行监测模型或复算论文分数。引用不是背书，同行评审不是证明，来源自报不是独立证据；发表或归档不建立一般串谋检测有效性，实现成功也不建立普遍有效性。</p><ol><li>莫欣与拉赫曼，《串谋探针读取了什么？评估多智能体串谋监测器的三个陷阱》，预印本 arXiv（预印本平台）编号 2611.10620，版本 v1，实验比较、时点与迁移部分，2026-11-12 已读快照。<a href="https://arxiv.org/html/2611.10620v1" target="_blank" rel="noreferrer">论文</a>。</li><li>研究项目作者，固定版本的指令测试源码，严格选择与场景组交叉拟合路径，2026-11-12 已读快照。<a href="https://github.com/mainul3195/collusion-probe-pitfalls/blob/d4adba6120246098b7f54dddd6af0782b4a47662/code/instruction_tests.py" target="_blank" rel="noreferrer">标签源码</a>。 固定源码提交：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d4adba6120246098b7f54dddd6af0782b4a47662</span></span></code></pre></div><ol start="3"><li>本研究中心，<a href="/joinwell52/assets/evidence/2026-11-12-sig-20261112-006/006-experiment.json">2026-11-12 内部隔离函数实验记录</a>：六个合成选择用例、四组选项替换用例及已披露的均值适配。不是数据集复现或模型评估。</li><li>研究项目作者，固定提交的生成器与预注册修订 7，2026-11-12 已读快照。<a href="https://github.com/mainul3195/collusion-probe-pitfalls/blob/d4adba6120246098b7f54dddd6af0782b4a47662/code/gen_e2v2.py" target="_blank" rel="noreferrer">生成器</a>；<a href="https://github.com/mainul3195/collusion-probe-pitfalls/tree/d4adba6120246098b7f54dddd6af0782b4a47662/prereg" target="_blank" rel="noreferrer">预注册记录</a>。</li><li>研究项目作者，无简报实验结果文件，固定提交的存储结果，未重跑。<a href="https://raw.githubusercontent.com/mainul3195/collusion-probe-pitfalls/d4adba6120246098b7f54dddd6af0782b4a47662/results/paper1/nobrief/main.json" target="_blank" rel="noreferrer">作者结果</a>。</li><li>Zenodo（研究成果归档平台），修正版 1.2 的作者归档描述，2026-11-12 已读元数据。<a href="https://doi.org/10.5281/zenodo.23636508" target="_blank" rel="noreferrer">归档身份</a>。</li></ol><h2 id="真正仍需补充的是片段证据" tabindex="-1">真正仍需补充的是片段证据 <a class="header-anchor" href="#真正仍需补充的是片段证据" aria-label="Permalink to &quot;真正仍需补充的是片段证据&quot;">​</a></h2><p>下一项有区分力的证据，是对修正后的原始片段独立核验标签与排除情况：缺失是否真实存在，混合行为占多少，独立标注者是否同意私有立场判定。之后才能检验阈值在现实、变化中的诚实流量上是否保持预期误报，以及无简报分离来自目标还是训练风格残留。</p><p>本次能够回答的是函数怎样选择比较对象，尚不能回答这些人群在实际数据中占多少，更不能据此判断一般串谋能否被识别。先交代标签留下了谁，分数才有明确的解释对象。</p>',31))])}const _=l(s,[["render",p]]);export{m as __pageData,_ as default};
